mod tests {
    use super::*;

    #[test]
    fn should_return_correct_tool_counts() {
        assert_eq!(tools_for_profile(ToolProfile::Minimal).len(), 5);
        assert_eq!(tools_for_profile(ToolProfile::Standard).len(), 10);
        assert_eq!(tools_for_profile(ToolProfile::Full).len(), 16);
