    #[test]
    fn should_check_tool_allowed() {
        assert!(is_tool_allowed(ToolProfile::Minimal, "ask_question"));
        assert!(!is_tool_allowed(ToolProfile::Minimal, "doctor"));
        assert!(is_tool_allowed(ToolProfile::Full, "doctor"));
    }

    #[test]
